mapper.select:
SELECT
    t.id, t.member_id, t.category_id, t.title, t.content,
    t.due_date, t.completed, t.created_at, t.updated_at,
    c.name AS category_name
FROM todo t
LEFT JOIN category c ON t.category_id = c.id
WHERE t.member_id = #{memberId}

    AND t.category_id = #{categoryId}


    AND t.completed = #{completed}

ORDER BY t.completed ASC, (t.due_date IS NULL) ASC, t.due_date ASC, t.id DESC

mapper.delete:
DELETE FROM todo
WHERE id = #{id}
  AND member_id = #{memberId}

mapper.update:
UPDATE todo
SET completed  = NOT completed,
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND member_id = #{memberId}
